return static function (FrameworkConfig $framework): void {
    $framework->rateLimiter()
        ->limiter('two_per_minute')
            ->policy('fixed_window')
            ->limit(2)
            ->interval('1 minute')
        ;

    $framework->rateLimiter()
        ->limiter('five_per_hour')
            ->policy('fixed_window')
            ->limit(5)
            ->interval('1 hour')
        ;

    $framework->rateLimiter()
        ->limiter('contact_form')
            ->policy('compound')
            ->limiters(['two_per_minute', 'five_per_hour'])
        ;
};

